contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run sends an arbitrary amount 'amount' to c.go and then checks the invariant
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to forward 'amount' to c.go
        require(address(this).balance >= amount);

        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // call go with provided amount; record if it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner and balances after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceC = address(c).balance;

        // General rule: owner never changes and c's balance is zero after the call.
        // Also assert that the test completed (we reached the assert).
        assert(ownerAfter == ownerBefore && balanceC == 0);
    }

    // allow receiving Ether when target calls back
    receive() external payable {}
}

